using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip no longer uses the system renderer by default.
        // Opt back into the classic professional look explicitly.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows a dropdown editor safely, guarding against the .NET 9 breaking change
    /// where passing null to DropDownControl throws ArgumentNullException.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        // .NET 9 breaking change: DropDownControl(null) now throws ArgumentNullException
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

